def list_commands(category=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, time, hashlib, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0301000" if __import__("os").path.isdir("./environment_mix/0301000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    ts = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Request logging (best-effort; does not fail the call)
    def _log(status, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            row = {
                "id": "req_" + hashlib.sha256(f"list_commands|{ts}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24],
                "endpoint": "list_commands",
                "timestamp": ts,
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "meta": meta or {}
            }
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            return

    # Validate inputs
    if category is not None and not isinstance(category, str):
        _log("error", {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "category must be a string")
    if isinstance(category, str) and category.strip() == "":
        _log("error", {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "category must not be empty")

    if limit is None:
        limit = 100
    if not isinstance(limit, int):
        _log("error", {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 1000:
        _log("error", {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "limit must be between 1 and 1000")

    if cursor is not None and not isinstance(cursor, str):
        _log("error", {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "cursor must be a string")

    if sort_by is None:
        sort_by = "name"
    if sort_by not in ("name", "category"):
        _log("error", {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "sort_by must be one of: name, category")

    if sort_order is None:
        sort_order = "asc"
    if sort_order not in ("asc", "desc"):
        _log("error", {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "sort_order must be one of: asc, desc")

    raw = _load("commands.json")
    commands = raw.get("rows") if isinstance(raw, dict) and isinstance(raw.get("rows"), list) else (raw if isinstance(raw, list) else [])
    # Normalize rows to dicts only
    commands = [c for c in commands if isinstance(c, dict)]

    # Determine known categories
    known_categories = sorted({c.get("category") for c in commands if isinstance(c.get("category"), str) and c.get("category").strip() != ""})

    if category is not None:
        if category not in known_categories:
            _log("error", {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Unknown category filter; category does not exist in the current catalog", known_categories=known_categories)
        filtered = [c for c in commands if c.get("category") == category]
    else:
        filtered = list(commands)

    reverse = (sort_order == "desc")
    def _k(row):
        v = row.get(sort_by)
        if v is None:
            return ""
        if isinstance(v, str):
            return v.casefold()
        return str(v).casefold()

    filtered.sort(key=_k, reverse=reverse)

    # Cursor handling: opaque, tied to this catalog sort/filter state
    # cursor = base64url("v1:<offset>:<sha>")
    def _state_sig():
        h = hashlib.sha256()
        # Signature depends on the sorted names list + filters + ordering so stale cursors are rejected
        h.update(f"sort_by={sort_by}|sort_order={sort_order}|category={category or ''}|count={len(filtered)}".encode("utf-8"))
        for r in filtered:
            h.update(b"\n")
            h.update(str(r.get("name", "")).encode("utf-8"))
        return h.hexdigest()[:24]

    offset = 0
    if cursor:
        try:
            payload = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            s = payload.decode("utf-8")
            if not s.startswith("v1:"):
                raise ValueError("bad prefix")
            parts = s.split(":")
            if len(parts) != 3:
                raise ValueError("bad parts")
            offset = int(parts[1])
            sig = parts[2]
            if offset < 0:
                raise ValueError("bad offset")
            if sig != _state_sig():
                _log("error", {"code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "Unrecognized cursor for this catalog")
        except ValueError:
            _log("error", {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Unrecognized cursor for this catalog")

    page = filtered[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < len(filtered)
    next_cursor = None
    if has_more:
        sig = _state_sig()
        token = f"v1:{next_offset}:{sig}".encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(token).decode("utf-8").rstrip("=")

    # Only return the published fields
    items = [{"name": c.get("name"), "description": c.get("description"), "category": c.get("category")} for c in page]

    resp = {
        "commands": items,
        "total": len(filtered),
        "limit": limit,
        "cursor": cursor,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "sort_by": sort_by,
        "sort_order": sort_order,
        "category": category,
    }
    _log("ok", {"returned": len(items), "total": len(filtered)})
    return resp

