def get_security_rules(**_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0301000" if __import__("os").path.isdir("./environment_mix/0301000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    ts = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_list_rows(raw):
        if isinstance(raw, dict) and isinstance(raw.get("rows"), list):
            rows = raw.get("rows")
        elif isinstance(raw, list):
            rows = raw
        else:
            rows = []
        return [r for r in rows if isinstance(r, dict)]

    def _log(status, code=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        rid = "req_" + str(int(time.time() * 1000)) + "_" + str(time.time_ns())[-8:]
        row = {
            "id": rid,
            "endpoint": "get_security_rules",
            "timestamp": ts,
            "status": status,
            "code": code,
            "latency_ms": int((time.time() - t0) * 1000),
            "meta": meta or {},
        }
        logs.append(row)
        _save("request_logs.json", logs)

    # Endpoint accepts no parameters
    if _extra:
        _log("error", "VALIDATION_ERROR", {"unexpected_fields": sorted(_extra.keys())})
        return _err("VALIDATION_ERROR", "This endpoint does not accept parameters", unexpected_fields=sorted(_extra.keys()))

    # Return published rules if present; otherwise return defaults (do NOT treat empty store as unauthorized)
    raw = _load("security_rules.json")
    rules_rows = _ensure_list_rows(raw)

    if rules_rows:
        rules = rules_rows[0]
        out = {
            "allow_shell_operators": bool(rules.get("allow_shell_operators")) if isinstance(rules.get("allow_shell_operators"), bool) else rules.get("allow_shell_operators"),
            "allowed_commands": rules.get("allowed_commands") if isinstance(rules.get("allowed_commands"), list) else (rules.get("allowed_commands") if rules.get("allowed_commands") is None else []),
            "disallowed_commands": rules.get("disallowed_commands") if isinstance(rules.get("disallowed_commands"), list) else (rules.get("disallowed_commands") if rules.get("disallowed_commands") is None else []),
            "allowed_tools": rules.get("allowed_tools") if isinstance(rules.get("allowed_tools"), list) else (rules.get("allowed_tools") if rules.get("allowed_tools") is None else []),
        }
        _log("ok", None, {"published": True})
        return {"security_rules": out}

    # Defaults when no rows exist (store digest shows 0 rows in this environment)
    out = {
        "allow_shell_operators": False,
        "allowed_commands": [],
        "disallowed_commands": [],
        "allowed_tools": [],
    }
    _log("ok", None, {"published": False})
    return {"security_rules": out}
